class Solution {
    public boolean canFormArray(int[] arr,int[][] pieces){
        Map<Integer,int[]> byFirst=new HashMap<>();
        for(int[] piece:pieces)byFirst.put(piece[0],piece);
        int index=0;
        while(index<arr.length){
            int[] piece=byFirst.get(arr[index]);
            if(piece==null)return false;
            for(int value:piece)if(index>=arr.length||arr[index++]!=value)return false;
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun canFormArray(arr:IntArray,pieces:Array<IntArray>):Boolean{
        val byFirst=pieces.associateBy{
            it[0]
        };
        var index=0;
        while(index<arr.size){
            val piece=byFirst[arr[index]]?:return false;
            for(value in piece)if(index>=arr.size||arr[index++]!=value)return false
        };
        return true
    }
}

